def list_risks(path="status_update.txt"):
    for line in open(path):
        line = line.strip(" -\n")
        if not line or line.startswith("Status"):
            continue
        print("- RISK:", line)

# every line becomes a "risk" —
# no type, no owner, no date

# each row the model returns:
#   {item, type, owner, date}
LANES = ["Risk", "Assumption", "Issue", "Dependency"]
def gap(r): return not r["owner"] or not r["date"]

for lane in LANES:
    for r in [x for x in rows if x["type"] == lane]:
        print(lane[0], r["item"],
              r["owner"] or "NO OWNER",
              r["date"]  or "NO DATE",
              "GAP" if gap(r) else "")
